use anyhow::Result;

use crate::test;
use crate::test::helper::human_mapping::assert_matches_human_painting_within_limit;
use crate::test::helper::human_mapping::invariants::assert_ground_truth_invariants_with_known_violations;

#[test]
fn mapping() -> Result<()> {
    // Recorded as found, not examined.
    test::helper::human_mapping::assert_matches_human_mapping_within_limit(
        "c-protocolbuffers-protobuf-this-must-be-autogenerated",
        27,
        27,
    )
}

#[test]
fn painting() -> Result<()> {
    assert_matches_human_painting_within_limit(
        "c-protocolbuffers-protobuf-this-must-be-autogenerated",
        4.22,
    )
}

#[test]
fn invariants() -> Result<()> {
    // Invariant 11, both presets: the removed `UPB_DESC` on before row 122 is left unpainted.
    // Invariant 12, both presets: `FeatureSetDefaults_parse` ->
    // `google_protobuf_FeatureSetDefaults_parse` (before row 123, after row 122) is painted on
    // neither side. Invariant 16, three times: that rename is not painted as its differing words
    // `google_protobuf_` under Minimal, nor entire under Full. Invariant 5: Full leaves columns
    // 58..59 of before row 144 unpainted between two painted regions. Invariant 25, 2 time(s): the
    // deleted `expression_statement` on before row 454 starts delete but its `;` is unpainted
    // (both presets).
    assert_ground_truth_invariants_with_known_violations(
        "c-protocolbuffers-protobuf-this-must-be-autogenerated",
        10,
    )
}
